import csv
import io

FIELDS = ('sku', 'name', 'qty')


def _parse(text):
    reader = csv.reader(io.StringIO(text))
    header = next(reader, None)
    if header is None:
        raise ValueError('missing header')
    header = [h.strip() for h in header]
    if sorted(header) != sorted(FIELDS):
        raise ValueError('header must be sku,name,qty')
    items = []
    seen = set()
    for line_no, row in enumerate(reader, start=2):
        if not row:
            continue
        if len(row) != len(header):
            raise ValueError(f'row {line_no}: expected {len(header)} fields')
        record = {k: v.strip() for k, v in zip(header, row)}
        sku, name, qty = record['sku'], record['name'], record['qty']
        if not sku:
            raise ValueError(f'row {line_no}: empty sku')
        if not name:
            raise ValueError(f'row {line_no}: empty name')
        if not qty or not all('0' <= c <= '9' for c in qty):
            raise ValueError(f'row {line_no}: invalid qty {qty!r}')
        if sku in seen:
            raise ValueError(f'row {line_no}: duplicate sku {sku!r}')
        seen.add(sku)
        items.append({'sku': sku, 'name': name, 'qty': int(qty)})
    return items


def import_text(text, store, dry_run=False):
    items = _parse(text)
    result = {'created': 0, 'updated': 0, 'unchanged': 0, 'changes': []}
    pending = []
    for item in items:
        before = store.get(item['sku'])
        if before == item:
            result['unchanged'] += 1
            continue
        result['created' if before is None else 'updated'] += 1
        result['changes'].append({'sku': item['sku'], 'before': before, 'after': dict(item)})
        pending.append(item)
    if not dry_run:
        for item in pending:
            store.put(item)
    return result

